const englishFallbackTranslations = { ...translations.en, ...commonTranslations.en, ...visualizationTranslations.en, ...pythonRunnerTranslations.en }

const translateString = (source: string, language: Language, dictionary: Record<string, string>) => {
  if (language === 'fr') return source
  const applyDictionary = (text: string, entries: Record<string, string>) => {
    let result = text
    Object.entries(entries).sort(([a], [b]) => b.length - a.length).forEach(([from, to]) => {
      result = result.split(from).join(to)
    })
    return result
  }
  const localized = applyDictionary(source, dictionary)
  return language === 'en' ? localized : applyDictionary(localized, englishFallbackTranslations)
}

const translateTree = (language: Language) => {
  const dictionary = language === 'fr' ? {} : { ...translations[language], ...commonTranslations[language], ...visualizationTranslations[language], ...pythonRunnerTranslations[language] }
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
  const nodes: Text[] = []
  let node: Node | null
  while ((node = walker.nextNode())) {
    const textNode = node as Text
    if (!originalText.has(textNode)) originalText.set(textNode, textNode.nodeValue ?? '')
    nodes.push(textNode)
  }
  nodes.forEach(textNode => {
    const current = textNode.nodeValue ?? ''
    const lastTranslated = lastTranslatedText.get(textNode)
    if (lastTranslated !== undefined && current !== lastTranslated) originalText.set(textNode, current)
    const source = originalText.get(textNode) ?? ''
    if (!source.trim()) return
    const translated = translateString(source, language, dictionary)
    if (textNode.nodeValue !== translated) textNode.nodeValue = translated
    lastTranslatedText.set(textNode, translated)
  })
  document.body.querySelectorAll('*').forEach(element => {
    const originals = originalAttribute.get(element) ?? new Map<string, string>()
    const last = lastTranslatedAttribute.get(element) ?? new Map<string, string>()
    for (const attribute of ['aria-label', 'placeholder', 'title']) {
      const current = element.getAttribute(attribute)
      if (current === null) continue
      if (!originals.has(attribute) || (last.has(attribute) && current !== last.get(attribute))) originals.set(attribute, current)
      const translated = translateString(originals.get(attribute) ?? current, language, dictionary)
      if (current !== translated) element.setAttribute(attribute, translated)
      last.set(attribute, translated)
    }
    originalAttribute.set(element, originals)
    lastTranslatedAttribute.set(element, last)
  })
}

let activeLanguageForTranslation: Language | null = null

export default function Page() {
  const [language, setLanguage] = useState<Language>('fr')
  useEffect(() => {
    activeLanguageForTranslation = language
    document.documentElement.lang = language
    document.documentElement.dir = language === 'ar' ? 'rtl' : 'ltr'
    translateTree(language)
    const Observer = window.MutationObserver
    if (!Observer) return () => {
      activeLanguageForTranslation = null
    }
    const translationObserver = new Observer(() => {
      if (activeLanguageForTranslation) translateTree(activeLanguageForTranslation)
    })
    translationObserver.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['aria-label', 'placeholder', 'title'] })
    return () => {
      translationObserver.disconnect()
      activeLanguageForTranslation = null
    }
  }, [language])
  const labels = languageLabels[language]
  const localizedNav = [
    { label: labels.learn, icon: Network, href: '#learn' },
    { label: labels.experiment, icon: Code2, href: '#experiment' },
    { label: labels.visualize, icon: Activity, href: '#visualize' },
    { label: labels.quiz, icon: CircleHelp, href: '#quiz' },
  ]
  const [history, setHistory] = useState(() => trainLinear(.1, 20))
  const [learningRate, setLearningRate] = useState(.1)
  const [manualDone, setManualDone] = useState(false)
  const [active, setActive] = useState('#learn')
  const run = (next: History, nextLearningRate: number) => { setHistory(next); setLearningRate(nextLearningRate); document.getElementById('visualize')?.scrollIntoView({ behavior: 'smooth' }) }
  const progress = useMemo(() => (manualDone ? 35 : 15), [manualDone])
  return <main className="min-h-screen bg-[#f7f9fc] text-slate-950"><header className="sticky top-0 z-20 border-b bg-white/90 backdrop-blur"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-4 px-4 py-3 lg:px-8"><a href="#top" className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-slate-950 text-white shadow-sm"><Sparkles /></div><div><p className="text-sm font-bold tracking-tight">Neural Network</p><p className="text-xs text-violet-600">Learning Lab</p></div></a><div className="flex items-center gap-2"><label className="flex items-center gap-1.5 rounded-lg border bg-white px-2.5 py-2 text-xs font-medium text-slate-700 shadow-sm"><Languages className="size-4 text-violet-600" /><span className="sr-only">{labels.choose}</span><select aria-label={labels.choose} value={language} onChange={event => { const next = event.target.value as Language; setLanguage(next); document.documentElement.lang = next }} className="bg-transparent outline-none"><option value="fr">Français</option><option value="en">English</option><option value="es">Español</option><option value="ar">العربية</option><option value="hi">हिन्दी</option><option value="tr">Türkçe</option><option value="pt">Português</option></select></label><div className="hidden items-center gap-2 md:flex"><Badge variant="outline" className="gap-1.5 border-emerald-200 bg-emerald-50 text-emerald-700"><span className="size-1.5 rounded-full bg-emerald-500" />{labels.session}</Badge><div className="flex items-center gap-2 text-xs text-muted-foreground"><Progress value={progress} className="w-20" />{progress}%</div></div></div></div></header><div id="top" className="mx-auto grid max-w-[1500px] lg:grid-cols-[240px_1fr]"><aside className="hidden border-r bg-white/70 px-4 py-7 lg:block"><div className="sticky top-24 space-y-6"><div><p className="mb-3 px-3 text-xs font-semibold uppercase tracking-widest text-muted-foreground">{labels.journey}</p><nav className="grid gap-1">{localizedNav.map(({ label, icon: Icon, href }) => <a key={href} href={href} onClick={() => setActive(href)} className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors ${active === href ? 'bg-slate-950 font-medium text-white' : 'text-slate-600 hover:bg-slate-100'}`}><Icon />{label}</a>)}</nav></div><Separator /><div className="rounded-xl bg-violet-50 p-4"><Zap className="mb-3 text-violet-600" /><p className="text-sm font-semibold">Objectif du jour</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Comprendre comment une erreur devient une mise à jour.</p></div></div></aside><div className="min-w-0 px-4 py-8 sm:px-6 lg:px-10 lg:py-12"><div className="mx-auto max-w-6xl space-y-16"><section className="relative overflow-hidden rounded-3xl bg-slate-950 px-6 py-10 text-white shadow-xl sm:px-10"><div className="absolute -right-24 -top-24 size-72 rounded-full bg-violet-500/20 blur-3xl" /><div className="absolute -bottom-32 left-1/3 size-80 rounded-full bg-blue-500/15 blur-3xl" /><div className="relative max-w-3xl"><Badge className="mb-5 border-blue-300/30 bg-blue-400/10 text-blue-200 hover:bg-blue-400/10">LABORATOIRE INTERACTIF · 01</Badge><h1 className="text-4xl font-bold tracking-tight sm:text-6xl">Comprendre comment les modèles apprennent.</h1><p className="mt-5 max-w-2xl text-base leading-7 text-slate-300 sm:text-lg">Une expérience guidée pour passer des équations de rétropropagation à une simulation vivante de descente de gradient.</p><div className="mt-7 flex flex-wrap gap-3"><a href="#learn" className="inline-flex h-9 items-center justify-center gap-2 rounded-lg bg-white px-4 text-sm font-medium text-slate-950 shadow-sm transition-colors hover:bg-slate-100">Commencer l’activité<ArrowRight /></a><a href="#visualize" className="inline-flex h-9 items-center justify-center rounded-lg border border-slate-600 bg-transparent px-4 text-sm font-medium text-white transition-colors hover:bg-slate-800">Voir le modèle en action</a></div></div></section><ManualActivity language={language} onContinue={() => { setManualDone(true); document.getElementById('experiment')?.scrollIntoView({ behavior: 'smooth' }) }} onRestart={() => { setManualDone(false); document.getElementById('learn')?.scrollIntoView({ behavior: 'smooth' }) }} /><Card className="border-violet-200 bg-violet-50 shadow-sm"><CardContent className="grid gap-5 p-6 md:grid-cols-2"><div><div className="mb-3 flex items-center gap-2 text-violet-800"><GitBranch /> <span className="font-semibold">Même mécanisme, autre focale</span></div><h3 className="text-lg font-bold leading-snug text-slate-950">De 4 paramètres à 2 paramètres</h3><p className="mt-2 text-sm leading-6 text-slate-700">Le premier réseau contient un neurone caché sigmoïde et une sortie linéaire. Ici, un neurone linéaire isole le cœur de la descente de gradient : un poids, un biais et des dérivées directes.</p></div><div className="grid grid-cols-2 gap-3 text-sm"><div className="rounded-xl border bg-white p-4"><p className="font-semibold text-slate-900">Activité 1</p><p className="mt-2 text-slate-700">1 entrée · sigmoïde cachée<br />4 paramètres · chaîne complète</p></div><div className="rounded-xl border bg-white p-4"><p className="font-semibold text-slate-900">Activité 2</p><p className="mt-2 text-slate-700">1 neurone linéaire<br />2 paramètres · dérivées directes</p></div></div></CardContent></Card><CodeLab onRun={run} unlocked={manualDone} language={language} /><TrainingLab history={history} learningRate={learningRate} setLearningRate={v => { setLearningRate(v); setHistory(trainLinear(v, 20)) }} language={language} /><QuizSection /></div></div></div><footer className="border-t bg-white py-8 text-center text-sm text-muted-foreground">Neural Network Learning Lab · {labels.footer}</footer></main>
}
